{
  "command": "ls -la && python3 -c "
from docx import Document
d=Document('内分泌专科入院评估.docx')
txt='\n'.join(p.text for p in d.paragraphs)
for t in d.tables:
    for r in t.rows:
        txt+='\n'+' | '.join(c.text for c in r.cells)
import re
print('chars',len(txt))
for k in ['待查','待评估','需要排除','不能','未回报','妊娠','主治医师审核','床位周转','外院人工转录','同型半胱氨酸','Z ≥ 2','copeptin','3.8 L','1.03','0.93']:
    print(k, txt.count(k))
print('一级标题:', re.findall(r'^[一二三四五六]、.*', txt, re.M))
"",
  "description": "Verify final outputs and docx key content"
}

{
  "command": "python3 -c "
from docx import Document
d=Document('内分泌专科入院评估.docx')
txt='\n'.join(p.text for p in d.paragraphs)
for t in d.tables:
    for r in t.rows: txt+='\n'+' | '.join(c.text for c in r.cells)
import re
for m in re.finditer(r'.{60}(5\.7|21\.7|30\.6|14\.6|6\.3%|4\+|尿酮 \+).{60}', txt):
    print('...', m.group(0).replace(chr(10),' '), '...')
    print('---')
"",
  "description": "Check labeling of transcribed lab values in docx"
}

